<?php $items = \Moves\Services\CmsShowcase::publicTestimonials(); if ($items === []) { return; } ?>
<section class="rz-section rz-testimonials"><div class="container"><div class="rz-section-intro"><span class="rz-kicker">DEPOIMENTOS</span><h2>Quem usa o Realizze</h2></div><div class="rz-quotes"><?php foreach ($items as $t): ?><figure class="rz-quote"><div class="rz-stars" role="img" aria-label="<?= (int) $t['rating'] ?> de 5 estrelas"><?= str_repeat('★', (int) $t['rating']) ?></div><blockquote><?= $this->e($t['body']) ?></blockquote><figcaption><?php if ($t['photo_path']): ?><img src="<?= $this->e($t['photo_path']) ?>" alt="" width="44" height="44" loading="lazy"><?php endif; ?><span><strong><?= $this->e($t['person_name']) ?></strong><?php if ($t['company'] !== ''): ?><small><?= $this->e($t['company']) ?></small><?php endif; ?></span></figcaption></figure><?php endforeach; ?></div></div></section>
